import remapping from "@ampproject/remapping";
import type { DecodedSourceMap, EncodedSourceMap } from "@ampproject/remapping";

type SourceMap = DecodedSourceMap | EncodedSourceMap;

export default function mergeSourceMap(
  inputMap: SourceMap,
  map: SourceMap,
  sourceFileName: string,
): SourceMap {
  // Remapping expects the sources of the generated `map` to match the sources
  // it will load through the loader below. Babel generates the output map with
  // the (possibly Windows-style) source file name, so normalize it to the same
  // shape remapping will ask for.
  const source = sourceFileName.replace(/\\/g, "/");

  let found = false;
  const result = remapping(rootless(map), (s, ctx) => {
    if (s === source && !found) {
      found = true;
      // Clear the source so that chained maps below this one don't attempt to
      // resolve against it again.
      ctx.source = "";
      return rootless(inputMap);
    }

    return null;
  });

  if (typeof inputMap.sourceRoot === "string") {
    result.sourceRoot = inputMap.sourceRoot;
  }

  // `remapping` returns a `SourceMap` class instance. Spread it into a plain
  // object so callers always receive a standard `[object Object]` value whose
  // prototype is exactly `Object.prototype`.
  return { ...result };
}

function rootless(map: SourceMap): SourceMap {
  return {
    ...map,
    // Prevent `remapping` from resolving sources against a `sourceRoot`, which
    // would make them relative to the wrong file.
    sourceRoot: null,
  };
}

